mapper.delete:
DELETE
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND create_time <= now() - INTERVAL '#{timeFrame} month'

mapper.select:
SELECT primary_key, type, user_id, enterprise_code, result, business_type, remark, source, create_time, update_time, delete_flag FROM ${tableName} WHERE delete_flag = false AND enterprise_code = #{enterpriseCode}
AND type = #{type}
AND user_id = #{userId}
AND business_type = #{businessType}
ORDER BY create_time DESC
